import ast
import fnmatch
import json
import os
import re
import string
import tempfile
import time
from dataclasses import dataclass
from pathlib import Path


@dataclass
class BackupEntry:
    path: Path
    existed: bool
    content: str


class FileManager:
    """Pure-Python, Windows EDR-safe file system manager with atomic writes & disk undo."""

    IGNORE_DIRS = {
        ".git", "__pycache__", "node_modules", ".venv", "venv",
        "dist", "build", ".idea", ".vscode", ".pytest_cache", ".mypy_cache",
        ".chatbridge_undo",
    }
    BINARY_EXTS = {
        ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".pdf", ".zip",
        ".exe", ".dll", ".pyd", ".so", ".pyc", ".woff", ".woff2", ".ttf",
        ".mp3", ".mp4", ".db", ".sqlite", ".bin",
    }

    def __init__(self, root_dir: str | Path | None = None) -> None:
        self._root = Path(root_dir or os.getcwd()).resolve()

    @property
    def root(self) -> Path:
        return self._root

    @property
    def _undo_dir(self) -> Path:
        return self._root / ".chatbridge_undo"

    def set_root(self, new_root: str) -> Path:
        candidate = Path(new_root.strip()).resolve()
        if not candidate.is_dir():
            raise ValueError(f"Directory does not exist: {new_root}")
        self._root = candidate
        return self._root

    def safe_path(self, rel_path: str) -> Path:
        target = (self._root / rel_path.strip()).resolve()
        if not target.is_relative_to(self._root):
            raise ValueError(f"Access denied outside project root: {rel_path}")
        return target

    def browse_dirs(self, path_str: str = "") -> dict:
        """Pure-Python directory browser for Windows drives & folders (no subprocess)."""
        target = Path(path_str.strip()).resolve() if path_str.strip() else self._root
        if not target.is_dir():
            target = self._root

        drives = [f"{d}:\\" for d in string.ascii_uppercase if os.path.exists(f"{d}:\\")]
        dirs = []
        try:
            for entry in sorted(target.iterdir(), key=lambda p: p.name.lower()):
                if entry.is_dir() and not entry.name.startswith("."):
                    dirs.append({"name": entry.name, "path": str(entry)})
        except PermissionError:
            pass

        parent = str(target.parent) if target.parent != target else ""
        return {
            "current": str(target),
            "parent": parent,
            "drives": drives,
            "dirs": dirs,
        }

    def _load_ignore_patterns(self) -> list[str]:
        patterns = [".env", ".env.*"]
        for fname in (".gitignore", ".chatbridgeignore"):
            p = self._root / fname
            if p.is_file():
                for line in p.read_text(encoding="utf-8", errors="ignore").splitlines():
                    line = line.strip()
                    if line and not line.startswith("#"):
                        patterns.append(line.rstrip("/"))
        return patterns

    @staticmethod
    def _is_ignored(rel_posix: str, name: str, patterns: list[str]) -> bool:
        for pat in patterns:
            if fnmatch.fnmatch(name, pat) or fnmatch.fnmatch(rel_posix, pat):
                return True
        return False

    def scan_files(self, limit: int = 1500) -> list[dict]:
        items: list[dict] = []
        patterns = self._load_ignore_patterns()
        for dirpath, dirnames, filenames in os.walk(self._root):
            rel_dir = Path(dirpath).relative_to(self._root)
            kept_dirs = []
            for d in sorted(dirnames):
                if d in self.IGNORE_DIRS:
                    continue
                rel_d = (rel_dir / d).as_posix()
                if rel_d.startswith("./"):
                    rel_d = rel_d[2:]
                if not self._is_ignored(rel_d, d, patterns):
                    kept_dirs.append(d)
            dirnames[:] = kept_dirs

            for fname in sorted(filenames):
                p = Path(dirpath) / fname
                if p.suffix.lower() in self.BINARY_EXTS:
                    continue
                rel = p.relative_to(self._root).as_posix()
                if self._is_ignored(rel, fname, patterns):
                    continue
                try:
                    size = p.stat().st_size
                    items.append({
                        "path": rel,
                        "size": size,
                        "est_tokens": max(1, size // 4),
                    })
                except OSError:
                    continue
                if len(items) >= limit:
                    return items
        return items

    def smart_select(self, task: str, max_files: int = 12) -> list[dict]:
        """Selects relevant files by matching task keywords against filenames, contents, and Python imports."""
        keywords = [w.lower() for w in re.findall(r"[A-Za-z0-9_./-]{3,}", task)]
        stopwords = {"the", "and", "for", "with", "this", "that", "from", "into", "add", "fix", "edit", "make", "use"}
        terms = [k for k in dict.fromkeys(keywords) if k not in stopwords]

        files = self.scan_files(limit=800)
        scored: list[tuple[int, dict]] = []

        for f in files:
            path_l = f["path"].lower()
            score = 0
            for t in terms:
                if t in path_l:
                    score += 10
            if score == 0 and terms and f["size"] < 250_000:
                try:
                    content_l = self.read_raw(f["path"]).lower()
                    for t in terms[:8]:
                        if t in content_l:
                            score += 2
                except OSError:
                    pass
            if score > 0:
                scored.append((score, f))

        scored.sort(key=lambda x: (-x[0], x[1]["est_tokens"]))
        top_files = [item[1] for item in scored[:max_files]]

        # Expand 1-hop Python imports for top hits (added in outline mode to save tokens)
        selected_map: dict[str, dict] = {}
        all_paths = {f["path"]: f for f in files}
        for f in top_files:
            mode = "outline" if f["est_tokens"] > 4000 else "full"
            selected_map[f["path"]] = {"path": f["path"], "mode": mode, "tokens": f["est_tokens"]}
            if f["path"].endswith(".py") and len(selected_map) < max_files:
                try:
                    tree = ast.parse(self.read_raw(f["path"]))
                    for node in ast.walk(tree):
                        if isinstance(node, ast.ImportFrom) and node.module:
                            mod_path = node.module.replace(".", "/") + ".py"
                            if mod_path in all_paths and mod_path not in selected_map:
                                mf = all_paths[mod_path]
                                selected_map[mod_path] = {"path": mod_path, "mode": "outline", "tokens": mf["est_tokens"]}
                except SyntaxError:
                    pass

        return list(selected_map.values())[:max_files]

    def read_raw(self, rel_path: str) -> str:
        """Read exact raw text preserving original CRLF/LF line endings."""
        p = self.safe_path(rel_path)
        if not p.is_file():
            raise FileNotFoundError(f"File not found: {rel_path}")
        with p.open("r", encoding="utf-8", errors="replace", newline="") as fh:
            return fh.read()

    def read_text(self, rel_path: str, start_line: int | None = None, end_line: int | None = None) -> tuple[str, int]:
        text = self.read_raw(rel_path)
        lines = text.splitlines()
        total = len(lines)
        if start_line is None and end_line is None:
            return text, total
        s = max(1, start_line or 1)
        e = min(total, end_line or total)
        sliced = [f"{idx}: {lines[idx - 1]}" for idx in range(s, e + 1)]
        return "\n".join(sliced), total

    @staticmethod
    def _atomic_write(target: Path, content: str) -> None:
        target.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp_name = tempfile.mkstemp(dir=target.parent, prefix=".tmp_cb_", suffix=target.suffix)
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="") as fh:
                fh.write(content)
            os.replace(tmp_name, target)
        except Exception:
            if os.path.exists(tmp_name):
                os.unlink(tmp_name)
            raise

    def write_with_backup(self, rel_path: str, content: str, backups: list[BackupEntry]) -> None:
        p = self.safe_path(rel_path)
        existed = p.is_file()
        old = self.read_raw(rel_path) if existed else ""
        backups.append(BackupEntry(path=p, existed=existed, content=old))
        self._atomic_write(p, content)

    def commit_undo_batch(self, backups: list[BackupEntry]) -> None:
        if not backups:
            return
        self._undo_dir.mkdir(parents=True, exist_ok=True)
        batch_file = self._undo_dir / f"undo_{int(time.time() * 1000)}.json"
        payload = [
            {"path": str(b.path), "existed": b.existed, "content": b.content}
            for b in backups
        ]
        self._atomic_write(batch_file, json.dumps(payload, ensure_ascii=False))

    def undo_last(self) -> int:
        if not self._undo_dir.is_dir():
            return 0
        batches = sorted(self._undo_dir.glob("undo_*.json"))
        if not batches:
            return 0
        latest = batches[-1]
        entries = json.loads(latest.read_text(encoding="utf-8"))
        for entry in reversed(entries):
            p = Path(entry["path"])
            if entry["existed"]:
                self._atomic_write(p, entry["content"])
            elif p.exists():
                p.unlink()
        latest.unlink()
        return len(entries)

import ast
import difflib
import json
import re
from core.file_manager import BackupEntry, FileManager


class PatchEngine:
    """Parses edits, file requests, interactive questions, and goal status from AI responses."""

    EDIT_RE = re.compile(
        r'<<<EDIT\s+path=["\']([^"\']+)["\']\s*>>>\s*\r?\n<<<OLD>>>\r?\n(.*?)\r?\n<<<NEW>>>\r?\n(.*?)\r?\n<<<END>>>',
        re.DOTALL,
    )
    WRITE_RE = re.compile(
        r'<<<WRITE\s+path=["\']([^"\']+)["\']\s*>>>\s*\r?\n(.*?)\r?\n<<<END>>>',
        re.DOTALL,
    )
    NEED_RE = re.compile(r"<<<NEED_FILES>>>\r?\n(.*?)\r?\n<<<END>>>", re.DOTALL)
    ASK_RE = re.compile(r"<<<ASK>>>\r?\n(.*?)\r?\n<<<END>>>", re.DOTALL)
    PLAN_RE = re.compile(r"<<<PLAN>>>\r?\n(.*?)\r?\n<<<END>>>", re.DOTALL)
    STATUS_RE = re.compile(r"<<<STATUS:\s*(NEED_MORE|APPLIED_NEXT|DONE)\s*>>>")

    def __init__(self, file_manager: FileManager) -> None:
        self._fm = file_manager

    @staticmethod
    def _strip_wrappers(text: str) -> str:
        t = text.strip()
        if t.startswith("<<>>") and t.endswith("<<>>"):
            t = t[4:-4].strip()
        m = re.match(r"^```[a-zA-Z0-9_-]*\r?\n(.*)\r?\n```$", t, re.DOTALL)
        return m.group(1) if m else t

    def parse_response(self, response_text: str, fallback_path: str = "") -> dict:
        ops: list[dict] = []
        for m in self.EDIT_RE.finditer(response_text):
            ops.append({"type": "edit", "path": m.group(1), "old": m.group(2), "new": m.group(3)})
        for m in self.WRITE_RE.finditer(response_text):
            ops.append({"type": "write", "path": m.group(1), "content": m.group(2)})

        need_files: list[dict] = []
        for m in self.NEED_RE.finditer(response_text):
            for raw_line in m.group(1).splitlines():
                line = raw_line.strip()
                if not line:
                    continue
                if ":" in line:
                    path_part, spec_part = line.rsplit(":", 1)
                    spec_part = spec_part.strip().lower()
                    if "-" in spec_part:
                        s, e = spec_part.split("-", 1)
                        need_files.append({
                            "path": path_part.strip(),
                            "mode": "range",
                            "start": int(s) if s.isdigit() else "",
                            "end": int(e) if e.isdigit() else "",
                        })
                    elif spec_part in ("full", "outline"):
                        need_files.append({"path": path_part.strip(), "mode": spec_part})
                    else:
                        need_files.append({"path": line, "mode": "full"})
                else:
                    need_files.append({"path": line, "mode": "full"})

        questions: list[dict] = []
        for m in self.ASK_RE.finditer(response_text):
            lines = [l.strip() for l in m.group(1).splitlines() if l.strip()]
            if not lines:
                continue
            q_text = lines[0]
            opts = [l[1:].strip() for l in lines[1:] if l.startswith("-")]
            questions.append({"question": q_text, "options": opts})

        plan: list[dict] = []
        for m in self.PLAN_RE.finditer(response_text):
            for raw_line in m.group(1).splitlines():
                if not raw_line.strip():
                    continue
                indent = len(raw_line) - len(raw_line.lstrip(" \t"))
                clean = raw_line.strip().lstrip("-*•").strip()
                done = False
                if clean.startswith("[x]") or clean.startswith("[X]"):
                    done = True
                    clean = clean[3:].strip()
                elif clean.startswith("[ ]") or clean.startswith("[]"):
                    clean = clean.split("]", 1)[1].strip()
                if indent >= 2 and plan:
                    plan[-1]["subtasks"].append({"text": clean, "done": done})
                else:
                    plan.append({"text": clean, "done": done, "subtasks": []})

        status_match = self.STATUS_RE.search(response_text)
        status_flag = status_match.group(1) if status_match else ""

        if not ops and not need_files and not questions and not plan and fallback_path.strip() and response_text.strip():
            ops.append({
                "type": "write",
                "path": fallback_path.strip(),
                "content": self._strip_wrappers(response_text),
            })

        return {
            "ops": ops,
            "need_files": need_files,
            "questions": questions,
            "plan": plan,
            "status_flag": status_flag,
        }

    @staticmethod
    def _validate_syntax(rel_path: str, content: str) -> str | None:
        lower = rel_path.lower()
        if lower.endswith(".py"):
            try:
                ast.parse(content, filename=rel_path)
            except SyntaxError as e:
                return f"Python SyntaxError on line {e.lineno}: {e.msg}"
        elif lower.endswith(".json"):
            try:
                json.loads(content)
            except json.JSONDecodeError as e:
                return f"JSON SyntaxError on line {e.lineno}, col {e.colno}: {e.msg}"
        return None

    @staticmethod
    def _preserve_newlines(new_text: str, use_crlf: bool) -> str:
        normalized = new_text.replace("\r\n", "\n")
        return normalized.replace("\n", "\r\n") if use_crlf else normalized

    @staticmethod
    def _build_diff_lines(old_text: str, new_text: str, rel_path: str) -> list[dict]:
        raw_diff = difflib.unified_diff(
            old_text.splitlines(),
            new_text.splitlines(),
            fromfile=f"a/{rel_path}",
            tofile=f"b/{rel_path}",
            lineterm="",
        )
        structured = []
        for line in raw_diff:
            if line.startswith("+++") or line.startswith("---"):
                kind = "meta"
            elif line.startswith("@@"):
                kind = "hunk"
            elif line.startswith("+"):
                kind = "add"
            elif line.startswith("-"):
                kind = "del"
            else:
                kind = "ctx"
            structured.append({"kind": kind, "text": line})
        return structured

    def execute(self, ops: list[dict], apply_changes: bool = False) -> list[dict]:
        results: list[dict] = []
        backups: list[BackupEntry] = []

        for op in ops:
            rel = op["path"]
            try:
                if op["type"] == "edit":
                    old_full = self._fm.read_raw(rel)
                    use_crlf = "\r\n" in old_full
                    norm_full = old_full.replace("\r\n", "\n")
                    norm_old = op["old"].replace("\r\n", "\n")
                    norm_new = op["new"].replace("\r\n", "\n")

                    count = norm_full.count(norm_old)
                    if count == 0:
                        results.append({"path": rel, "status": "error", "message": "Sensitive OLD block not found (check exact case/indentation)."})
                        continue
                    if count > 1:
                        results.append({"path": rel, "status": "error", "message": f"Sensitive match found {count} occurrences; include more context lines."})
                        continue

                    new_full = self._preserve_newlines(norm_full.replace(norm_old, norm_new, 1), use_crlf)

                elif op["type"] == "write":
                    try:
                        old_full = self._fm.read_raw(rel)
                        use_crlf = "\r\n" in old_full
                    except FileNotFoundError:
                        old_full = ""
                        use_crlf = False
                    new_full = self._preserve_newlines(op["content"], use_crlf)
                else:
                    continue

                syntax_err = self._validate_syntax(rel, new_full)
                if syntax_err:
                    results.append({"path": rel, "status": "error", "message": syntax_err})
                    continue

                diff_lines = self._build_diff_lines(old_full, new_full, rel)
                if apply_changes:
                    self._fm.write_with_backup(rel, new_full, backups)
                results.append({
                    "path": rel,
                    "status": "applied" if apply_changes else "ready",
                    "diff_lines": diff_lines,
                })
            except Exception as e:
                results.append({"path": rel, "status": "error", "message": str(e)})

        if apply_changes:
            self._fm.commit_undo_batch(backups)
        return results

:root {
  --bg: #0b1120;
  --card: #111827;
  --panel: #0f172a;
  --border: #1f2937;
  --text: #e5e7eb;
  --muted: #9ca3af;
  --primary: #3b82f6;
  --success: #16a34a;
  --warn: #d97706;
  --add-bg: rgba(22, 163, 74, 0.18);
  --add-fg: #4ade80;
  --del-bg: rgba(220, 38, 38, 0.20);
  --del-fg: #f87171;
  --hunk-fg: #38bdf8;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); }
.topbar { display: flex; justify-content: space-between; align-items: center; padding: 12px 20px; background: var(--card); border-bottom: 1px solid var(--border); gap: 16px; }
.brand { font-weight: 700; font-size: 16px; display: flex; align-items: center; gap: 8px; white-space: nowrap; }
.badge { font-size: 11px; background: #1e3a8a; color: #93c5fd; padding: 2px 8px; border-radius: 999px; }
.badge.goal { background: #374151; color: #f3f4f6; }
.badge.goal.done { background: #14532d; color: #4ade80; }
.badge.goal.active { background: #78350f; color: #fbbf24; }
.project-bar { display: flex; gap: 8px; flex: 1; max-width: 620px; }
.layout { display: grid; grid-template-columns: 340px 1fr; gap: 16px; padding: 16px 20px; max-width: 1440px; margin: 0 auto; }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.card-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.card-head h3 { margin: 0; font-size: 14px; font-weight: 600; }
.sidebar { height: calc(100vh - 92px); }
.workspace { display: flex; flex-direction: column; gap: 16px; }
input, textarea, select { background: var(--panel); color: var(--text); border: 1px solid #374151; border-radius: 6px; padding: 8px 10px; font-size: 13px; width: 100%; }
textarea { min-height: 95px; resize: vertical; font-family: inherit; }
textarea.mono { font-family: ui-monospace, Consolas, monospace; font-size: 12px; }
textarea.small { min-height: 80px; }
.num-input { width: 95px; display: inline-block; margin-left: 4px; }
.row { display: flex; gap: 8px; align-items: center; }
.wrap { flex-wrap: wrap; }
.btn { border: none; border-radius: 6px; padding: 8px 12px; font-size: 13px; font-weight: 600; cursor: pointer; color: #fff; white-space: nowrap; }
.btn.primary { background: var(--primary); }
.btn.success { background: var(--success); }
.btn.warn { background: var(--warn); }
.btn.ghost { background: #374151; }
.btn:hover { filter: brightness(1.1); }
.file-list { flex: 1; overflow-y: auto; border: 1px solid var(--border); border-radius: 6px; padding: 6px; background: var(--panel); }
.fitem { display: flex; align-items: center; gap: 8px; padding: 4px 6px; border-radius: 4px; font-size: 12px; font-family: ui-monospace, monospace; cursor: pointer; }
.fitem:hover { background: #1e293b; }
.fitem input { width: auto; }
.fmeta { margin-left: auto; color: var(--muted); font-size: 11px; }
.token-meter { display: flex; justify-content: space-between; font-size: 12px; padding-top: 6px; border-top: 1px solid var(--border); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { display: flex; align-items: center; gap: 6px; background: #1e293b; border: 1px solid #334155; border-radius: 6px; padding: 4px 8px; font-size: 12px; }
.chip select { width: auto; padding: 2px 6px; font-size: 11px; }
.chip input.rng { width: 64px; padding: 2px 6px; font-size: 11px; }
.qa-container { display: flex; flex-direction: column; gap: 10px; }
.qa-card { background: #0f172a; border: 1px solid #3b82f6; border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 6px; }
.qa-title { font-weight: 600; font-size: 13px; color: #93c5fd; }
.qa-opt { display: flex; align-items: center; gap: 8px; font-size: 13px; cursor: pointer; }
.qa-opt input { width: auto; }
.diff-container { display: flex; flex-direction: column; gap: 10px; max-height: 360px; overflow-y: auto; }
.diff-file { border: 1px solid var(--border); border-radius: 6px; overflow: hidden; background: #020617; }
.diff-header { display: flex; justify-content: space-between; padding: 6px 10px; background: #1e293b; font-family: ui-monospace, monospace; font-size: 12px; font-weight: 600; }
.diff-header.ready, .diff-header.applied { color: var(--add-fg); }
.diff-header.error { color: var(--del-fg); }
.diff-body { font-family: ui-monospace, Consolas, monospace; font-size: 12px; line-height: 1.45; overflow-x: auto; }
.dline { padding: 1px 10px; white-space: pre; }
.dline.add { background: var(--add-bg); color: var(--add-fg); }
.dline.del { background: var(--del-bg); color: var(--del-fg); }
.dline.hunk { color: var(--hunk-fg); background: rgba(56, 189, 248, 0.08); }
.dline.meta { color: var(--muted); }
.muted { color: var(--muted); font-size: 12px; }
.chk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); cursor: pointer; }
.chk input { width: auto; }
.modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.65); display: flex; align-items: center; justify-content: center; z-index: 50; }
.modal.hidden { display: none; }
.modal-card { background: var(--card); border: 1px solid #334155; border-radius: 10px; padding: 16px; width: min(560px, 92vw); display: flex; flex-direction: column; gap: 10px; }
.hidden { display: none !important; }
.col { display: flex; flex-direction: column; gap: 8px; }

/* Tree explorer */
.tree-folder { display: flex; flex-direction: column; }
.tree-row { display: flex; align-items: center; gap: 6px; padding: 3px 6px; border-radius: 4px; font-size: 12px; font-family: ui-monospace, monospace; cursor: pointer; user-select: none; }
.tree-row:hover { background: #1e293b; }
.tree-row input[type="checkbox"] { width: auto; margin: 0; cursor: pointer; }
.tree-caret { width: 12px; text-align: center; color: var(--muted); font-size: 10px; }
.tree-children { display: flex; flex-direction: column; border-left: 1px dashed #334155; margin-left: 11px; padding-left: 6px; }
.tree-children.collapsed { display: none; }
.tree-folder-lbl { color: #93c5fd; font-weight: 600; }
